'use server';
import 'server-only';
import { randomBytes } from 'node:crypto';
import { z } from 'zod';
import { requireOwner } from '@/server/auth/guards';
import { revalidateTables } from '@/server/tenancy/invalidate';
import { err, ok, type ActionResult } from '@/lib/result';
import { mapDbError } from '@/lib/errors';

// Tables and QR codes (TAB-01 to TAB-03). Tokens: 128 random bits in base64url (22 characters),
// generated by the server; the old token stops working as soon as it is regenerated.

const slug = z.string().min(1).max(40);
const newToken = () => randomBytes(16).toString('base64url');
const label = z.string().trim().min(1).max(40);
const zone = z
  .string()
  .trim()
  .max(40)
  .transform((v) => (v.length === 0 ? null : v))
  .nullable();
const seats = z.number().int().min(1).max(100).nullable();

const tableSchema = z.object({ shopSlug: slug, label, zone, seats }).strict();

export async function createTableAction(
  input: z.input<typeof tableSchema>,
): Promise<ActionResult<number>> {
  const parsed = tableSchema.safeParse(input);
  if (!parsed.success) return err('VALIDATION', 'VALIDATION');
  const res = await requireOwner(parsed.data.shopSlug);
  if (!res.ok) return res;
  const { error, data } = await res.value.db.rpc('owner_create_tables', {
    p_shop_id: res.value.shop.id,
    p_tables: [
      {
        label: parsed.data.label,
        zone: parsed.data.zone,
        seats: parsed.data.seats,
        token: newToken(),
      },
    ],
  });
  if (error) return err(error.code === '23505' ? 'LABEL_TAKEN' : mapDbError(error).code, 'ERROR');
  revalidateTables(res.value.shop.id);
  return ok(Number(data));
}

const batchSchema = z
  .object({
    shopSlug: slug,
    prefix: z.string().trim().max(30),
    from: z.number().int().min(0).max(9999),
    to: z.number().int().min(0).max(9999),
    zone,
    seats,
  })
  .strict()
  .refine((v) => v.to >= v.from && v.to - v.from < 200, { message: 'range' });

/** "Tables 1 to 20, zone Salle" in one go (max. 200). */
export async function createTablesBatchAction(
  input: z.input<typeof batchSchema>,
): Promise<ActionResult<number>> {
  const parsed = batchSchema.safeParse(input);
  if (!parsed.success) return err('VALIDATION', 'VALIDATION');
  const res = await requireOwner(parsed.data.shopSlug);
  if (!res.ok) return res;
  const { prefix, from, to } = parsed.data;
  const tables = Array.from({ length: to - from + 1 }, (_, i) => ({
    label: `${prefix ? `${prefix} ` : ''}${from + i}`.slice(0, 40),
    zone: parsed.data.zone,
    seats: parsed.data.seats,
    token: newToken(),
  }));
  const { error, data } = await res.value.db.rpc('owner_create_tables', {
    p_shop_id: res.value.shop.id,
    p_tables: tables,
  });
  if (error) return err(error.code === '23505' ? 'LABEL_TAKEN' : mapDbError(error).code, 'ERROR');
  revalidateTables(res.value.shop.id);
  return ok(Number(data));
}

const updateSchema = z
  .object({ shopSlug: slug, id: z.uuid(), label, zone, seats, isActive: z.boolean() })
  .strict();

export async function updateTableAction(
  input: z.input<typeof updateSchema>,
): Promise<ActionResult<null>> {
  const parsed = updateSchema.safeParse(input);
  if (!parsed.success) return err('VALIDATION', 'VALIDATION');
  const res = await requireOwner(parsed.data.shopSlug);
  if (!res.ok) return res;
  const { error } = await res.value.db
    .from('dining_tables')
    .update({
      label: parsed.data.label,
      zone: parsed.data.zone,
      seats: parsed.data.seats,
      is_active: parsed.data.isActive,
    })
    .eq('id', parsed.data.id)
    .eq('shop_id', res.value.shop.id);
  if (error) return err(error.code === '23505' ? 'LABEL_TAKEN' : mapDbError(error).code, 'ERROR');
  revalidateTables(res.value.shop.id);
  return ok(null);
}

export async function rotateTableTokenAction(
  shopSlug: string,
  tableId: string,
): Promise<ActionResult<null>> {
  const res = await requireOwner(slug.parse(shopSlug));
  if (!res.ok) return res;
  const { error } = await res.value.db.rpc('owner_rotate_table_token', {
    p_table_id: z.uuid().parse(tableId),
    p_new_token: newToken(),
  });
  if (error) return err(mapDbError(error).code, 'ERROR');
  revalidateTables(res.value.shop.id);
  return ok(null);
}

export async function deleteTableAction(
  shopSlug: string,
  tableId: string,
): Promise<ActionResult<null>> {
  const res = await requireOwner(slug.parse(shopSlug));
  if (!res.ok) return res;
  const { error } = await res.value.db.rpc('owner_soft_delete', {
    p_entity: 'table',
    p_id: z.uuid().parse(tableId),
  });
  if (error) return err(mapDbError(error).code, 'ERROR');
  revalidateTables(res.value.shop.id);
  return ok(null);
}
